def soukatu_row(sheet, label):
    """総括表の1行を返す。label は行ラベルの後方一致でよい。"""
    for lab, unit, d in SOUKATU[sheet]["行"]:
        if lab == label or lab.endswith(label):
            return lab, unit, d
    raise KeyError((sheet, label))


def taikeikakuhi(sheet, label, nen):
    """対計画比（％）。公表値をそのまま返す。"""
    _lab, _u, d = soukatu_row(sheet, label)
    return d[nen]["対計画比"]


def chart_rows(key, block):
    """管理指標グラフの1ブロックを (見出し, [(区分, 行, 値…)]) で返す。"""
    b = CHART[key]["ブロック"][block]
    return b["見出し"], b["行"]


