    for sh, v in SOUKATU.items():
        print("%s  %s  %d行" % (sh, v["表題"], len(v["行"])))
    print()
    for k, v in CHART.items():
        print("%-4s %-22s %s" % (k, v["管理指標"], "／".join(v["ブロック"])))
